inline ::flatbuffers::Offset<ERMCoverage> CreateERMCoverage(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    uint64_t N = 0,
    uint32_t OBJECTS = 0,
    ermCoverageVerdict VERDICT = ermCoverageVerdict::Unspecified,
    double MEAN_D2 = std::numeric_limits<double>::quiet_NaN(),
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> INSIDE = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<double>> PIT = 0,
    double PIT_MAX_CDF_GAP = std::numeric_limits<double>::quiet_NaN(),
    uint64_t MISSING_MODEL = 0) {
  ERMCoverageBuilder builder_(_fbb);
  builder_.add_MISSING_MODEL(MISSING_MODEL);
  builder_.add_PIT_MAX_CDF_GAP(PIT_MAX_CDF_GAP);
  builder_.add_MEAN_D2(MEAN_D2);
  builder_.add_N(N);
  builder_.add_PIT(PIT);
  builder_.add_INSIDE(INSIDE);
  builder_.add_OBJECTS(OBJECTS);
  builder_.add_VERDICT(VERDICT);
  return builder_.Finish();
}

