  std::swap(PROPAGATOR_COVERAGE, o.PROPAGATOR_COVERAGE);
  std::swap(COMMON_EPOCH, o.COMMON_EPOCH);
  std::swap(COVARIANCE_MAP, o.COVARIANCE_MAP);
  std::swap(PAIR_STATISTICS, o.PAIR_STATISTICS);
  std::swap(CALIBRATION, o.CALIBRATION);
  std::swap(CALIBRATED_COVARIANCES, o.CALIBRATED_COVARIANCES);
  std::swap(CONSIDER_COVARIANCES, o.CONSIDER_COVARIANCES);
  std::swap(NOISE_RESPONSES, o.NOISE_RESPONSES);
  std::swap(ELEMENT_FITS, o.ELEMENT_FITS);
  std::swap(ATTACH_RECIPE, o.ATTACH_RECIPE);
