inline const ERM *GetERM(const void *buf) {
  return ::flatbuffers::GetRoot<ERM>(buf);
}

inline const ERM *GetSizePrefixedERM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<ERM>(buf);
}

inline const char *ERMIdentifier() {
  return "$ERM";
}

inline bool ERMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, ERMIdentifier());
}

inline bool SizePrefixedERMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, ERMIdentifier(), true);
}

template <bool B = false>
inline bool VerifyERMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<ERM>(ERMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedERMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<ERM>(ERMIdentifier());
}

inline void FinishERMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<ERM> root) {
  fbb.Finish(root, ERMIdentifier());
}

inline void FinishSizePrefixedERMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<ERM> root) {
  fbb.FinishSizePrefixed(root, ERMIdentifier());
}

inline std::unique_ptr<ERMT> UnPackERM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<ERMT>(GetERM(buf)->UnPack(res));
}

inline std::unique_ptr<ERMT> UnPackSizePrefixedERM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<ERMT>(GetSizePrefixedERM(buf)->UnPack(res));
}

